// Single source for the pixelized DigitalOcean loading symbol. Nothing is
// hand-drawn: the 16/24 grids are DERIVED from the product logo path
// (website/public/favicon.svg) by the downsample pipeline in
// design/downsample.mjs — hard supersampled raster, then one x-by-x coverage
// window per cell (mean alpha >= 0.5 keeps the cell) — so this mark can never
// drift from the logo.
//
// Outputs, regenerated by:  node design/pixel-do-loader-gen.mjs
//   design/pixel-do-loader.svg           standalone 24-grid sweep (review asset)
//   design/pixel-do-loader-16.svg        standalone 16-grid sweep (review asset)
//   design/pixel-do-twinkle.svg         standalone 24-grid twinkle face (review asset)
//   design/pixel-do-twinkle-16.svg      standalone 16-grid twinkle face (review asset)
//   design/pixel-do-loader-mockup.html  live review page
//   packages/client/ui-primitives/src/pixel-loader/generated.ts   shared cells + css
//   apps/desktop/renderer/spinner.svg  inline SMIL twinkle for the desktop splash
//   apps/desktop/renderer/startup.html splash spinner div rewritten in place
//   ../vscode/src/.../editor/media/letterpress-{dark,light,hcDark,hcLight}.svg
//     the twin's empty-editor mark: derived 16-grid twinkle face
//   ../.vscode-twin/dist/out/... same four files, when the staged dist exists
//
// The web sweep is a CSS animation: each 22.5-degree bucket of pixels is one
// <g class="dsh-pl">. Every bucket's animation-delay carries its own clockwise
// stagger (-k/16 of the cycle) added to the host-shifted sweep window
// (--dsh-boot-arc / --dsh-pixel-loader-boost), so the ladder runs around the
// mark instead of blinking in unison. The shared stylesheet ships once per
// document; bodies carry geometry only. Rendered pitch widens the pixel gap:
// at a 1:1-or-better pitch every face renders the chunkier 20% gap, and smaller
// renderings trade pixel mass for gap until 50% so the mark survives sub-1px
// cells. The desktop startup splash and the vscode letterpress idle as the
// twinkle (negative begin offsets) because their CSPs forbid dynamic styles.
import { mkdirSync, existsSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { deriveCells } from './downsample.mjs'

// The ground truth: the product logo vector path. The pipeline replaces the
// old hand-minted ASCII grids; bump COVERAGE only if a logo change ever sheds
// a feature the eye needs.
const LOGO_D = readFileSync(join(import.meta.dirname, '../website/public/favicon.svg'), 'utf8').match(/d="([^"]+)"/)[1]
const COVERAGE = 0.5

// Sweep recipe: F buckets of one shared cycle; each bucket's pixels pop to full
// color when the hand reaches them and decay down the ladder behind it.
// The step order is the clockwise bucket index (12 o'clock first), matching the
// approved mock: the light runs around the mark.
const F = 16
const PERIOD = 1.2
const DIM = 0.22
const LADDER = [1, 0.87, 0.74, 0.61, 0.48, 0.35, DIM]
// Per-cell inset at the chunkier 20% gap (a 0.8 cell in a 1-unit pitch): every
// face (sweep and twinkle) renders the fat pixels at 1:1-or-better pitch.
const TW_INSET = 0.1

// Twinkle recipe (idle brand mark, starting chat / boot / editor letterpress):
// every pixel runs its own pop-and-fade cycle — duration and negative delay
// drawn from a seeded PRNG so the field twinkles like an inference engine
// instead of sweeping the mark, and reruns stay byte-identical.
function mulberry32(seed) {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6D2B79F5) >>> 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
const TW_MIN_DUR = 1.6
const TW_SPAN_DUR = 1.8

/** Per-pixel [delay s (negative), duration s] twinkle schedule, parallel to the cell list. */
function twinkleSchedule(cellCount, seed) {
  const rand = mulberry32(seed)
  return Array.from({ length: cellCount }, () => {
    const dur = round2(TW_MIN_DUR + rand() * TW_SPAN_DUR)
    return [round2(-rand() * dur), dur]
  })
}

const ROOT = '/home/snguyen/dev/digitalocean/idk/deepseek-harness'
const VSCODE = join(ROOT, '../vscode')
const TWIN_DIST = join(ROOT, '../.vscode-twin/dist')
const DESIGN = `${ROOT}/design`
const MODULE_OUT = `${ROOT}/packages/client/ui-primitives/src/pixel-loader/generated.ts`
const DESKTOP_OUT = `${ROOT}/apps/desktop/renderer/spinner.svg`

function round2(n) { return Math.round(n * 100) / 100 }

/** Bucket derived cells into F clockwise sweep groups of [col,row]. */
function bucketsFor(cells, N) {
  const groups = Array.from({ length: F }, () => [])
  for (const [c, r] of cells) {
    const angle = Math.atan2(r + 0.5 - N / 2, c + 0.5 - N / 2) * 180 / Math.PI
    const f = ((((angle + 90) % 360) + 360) % 360) / 360
    groups[Math.round(f * F) % F].push([c, r])
  }
  return groups
}

function rectsFor(cells, inset, rx) {
  const side = round2(1 - 2 * inset)
  return cells.map(([c, r]) =>
    `<rect x="${round2(c + inset)}" y="${round2(r + inset)}" width="${side}" height="${side}" rx="${rx}"/>`).join('')
}

/** The sweep stylesheet shared by every document host. */
function styleBlock() {
  const steps = LADDER.map((value, i) => `${round2((i / F) * 100)}%{opacity:${value}}`).join('')
  return `.dsh-pl{animation:dsh-pl-sweep ${PERIOD}s step-end infinite}
@keyframes dsh-pl-sweep{${steps}100%{opacity:${DIM}}}
@media (prefers-reduced-motion: reduce){.dsh-pl{animation:none}}`
}

/** CSS mode: per-bucket clockwise delays, shiftable through custom properties. */
function innerCss(cells, inset, rx) {
  return cells.map((bucket, k) => {
    const begin = round2((k / F) * PERIOD)
    const delay = `calc(${begin}s + (var(--dsh-boot-arc, 72deg) - var(--dsh-pixel-loader-boost, 0) * 360deg) / 360deg * ${PERIOD}s)`
    return `<g opacity="${DIM}" class="dsh-pl" style="animation-delay: ${delay}">${rectsFor(bucket, inset, rx)}</g>`
  }).join('')
}

/** The twinkle stylesheet shared by every document host that idles the mark. */
function twinkleStyleBlock() {
  return `.dsh-pl-tw{animation-name:dsh-pl-twinkle;animation-iteration-count:infinite;animation-timing-function:cubic-bezier(.33,0,.25,1)}
@keyframes dsh-pl-twinkle{0%,62%,100%{opacity:${DIM}}9%{opacity:1}}
@media (prefers-reduced-motion: reduce){.dsh-pl-tw{animation:none}}`
}

/** SMIL twinkle mode: per-pixel pop & fade through negative begin offsets, no styles at all. */
function innerTwinkleSmil(flat, schedule, inset, rx) {
  const side = round2(1 - 2 * inset)
  return flat.map(([c, r], i) => {
    const [delay, dur] = schedule[i]
    return `<rect opacity="${DIM}" x="${round2(c + inset)}" y="${round2(r + inset)}" width="${side}" height="${side}" rx="${rx}"><animate attributeName="opacity" values="${DIM};1;${DIM};${DIM}" keyTimes="0;0.09;0.62;1" dur="${dur}s" begin="${delay}s" repeatCount="indefinite"/></rect>`
  }).join('')
}

/** CSS twinkle mode: one self-timed pop/fade rect per pixel; negative delays keep the field alive from first paint. */
function innerTwinkle(flat, schedule, inset, rx) {
  const side = round2(1 - 2 * inset)
  return flat.map(([c, r], i) => {
    const [delay, dur] = schedule[i]
    return `<rect class="dsh-pl-tw" style="animation-duration:${dur}s;animation-delay:${delay}s" x="${round2(c + inset)}" y="${round2(r + inset)}" width="${side}" height="${side}" rx="${rx}"/>`
  }).join('')
}

function svgFor(cells, { rx, width }) {
  const N = cellsWidth(cells)
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${N} ${N}" width="${width}" height="${width}" fill="currentColor" aria-hidden="true">
<style>
${styleBlock()}
</style>
${innerCss(cells, TW_INSET, rx)}
</svg>
`
}
function cellsWidth(cells) {
  let max = 0
  for (const bucket of cells) for (const [c, r] of bucket) max = Math.max(max, c, r)
  return max + 1
}

const CSS = styleBlock()
const TW_CSS = twinkleStyleBlock()
const flat24 = deriveCells(LOGO_D, 24, COVERAGE)
const flat16 = deriveCells(LOGO_D, 16, COVERAGE)
const cells24 = bucketsFor(flat24, 24)
const cells16 = bucketsFor(flat16, 16)
const sched24 = twinkleSchedule(flat24.length, 0xD0CE24)
const sched16 = twinkleSchedule(flat16.length, 0xD0CE16)
const big = svgFor(cells24, { rx: 0.18, width: 48 })
const small = svgFor(cells16, { rx: 0.12, width: 16 })
const bigTw = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="96" height="96" fill="currentColor" aria-hidden="true">
<style>
${TW_CSS}
</style>
${innerTwinkle(flat24, sched24, TW_INSET, 0.18)}
</svg>
`
const smallTw = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" width="128" height="128" fill="currentColor" aria-hidden="true">
<style>
${TW_CSS}
</style>
${innerTwinkle(flat16, sched16, TW_INSET, 0.18)}
</svg>
`
writeFileSync(`${DESIGN}/pixel-do-loader.svg`, big)
writeFileSync(`${DESIGN}/pixel-do-loader-16.svg`, small)
writeFileSync(`${DESIGN}/pixel-do-twinkle.svg`, bigTw)
writeFileSync(`${DESIGN}/pixel-do-twinkle-16.svg`, smallTw)

mkdirSync(dirname(MODULE_OUT), { recursive: true })
writeFileSync(MODULE_OUT, `/**
 * Generated by \`node design/pixel-do-loader-gen.mjs\` — do not edit by hand.
 * Clockwise sweep buckets of the pixelized DigitalOcean loading mark as
 * [column,row] cells: {@link PIXEL_LOADER_CELLS_24} and
 * {@link PIXEL_LOADER_CELLS_16}, derived by the hard-downsample pipeline in
 * design/downsample.mjs from the product logo path
 * (website/public/favicon.svg): one coverage window per cell keeps the mark
 * true to the vector at any grid. The clockwise order lights the buckets
 * 12-o'clock-first. Renderers turn buckets into rect markup (see ui-primitives
 * PixelLoader): one \`<g class="dsh-pl">\` per bucket, its \`animation-delay\`
 * the bucket's step plus the host-shifted sweep window; the shared stylesheet
 * {@link PIXEL_LOADER_CSS} carries the step-end ladder and the
 * prefers-reduced-motion guard once per document.
 */

/** One full sweep cycle, in seconds; every delay math follows it. */
export const PIXEL_LOADER_PERIOD_S = ${PERIOD}

/** Shared sweep stylesheet: discrete opacity ladder + reduced-motion guard. */
export const PIXEL_LOADER_CSS = \`${CSS}\`

/** Shared twinkle stylesheet: per-pixel pop & fade with a reduced-motion guard (idle brand mark). */
export const PIXEL_LOADER_TWINKLE_CSS = \`${TW_CSS}\`

/** Per-pixel [delay s, duration s] twinkle schedule, parallel to {@link PIXEL_LOADER_CELLS_24} flattened. */
export const PIXEL_LOADER_TWINKLE_24: readonly (readonly [number, number])[] = ${JSON.stringify(sched24)}

/** Per-pixel [delay s, duration s] twinkle schedule, parallel to {@link PIXEL_LOADER_CELLS_16} flattened. */
export const PIXEL_LOADER_TWINKLE_16: readonly (readonly [number, number])[] = ${JSON.stringify(sched16)}

/** 24x24 grid buckets: deep-diving, boot page, and 20px-and-up chrome. */
export const PIXEL_LOADER_CELLS_24: readonly (readonly (readonly [number, number])[])[] = ${JSON.stringify(cells24)}


/** 16x16 grid buckets: sidebar/picker/timeline small-chrome loading. */
export const PIXEL_LOADER_CELLS_16: readonly (readonly (readonly [number, number])[])[] = ${JSON.stringify(cells16)}

`)

// The idle splash logo twinkles (random dot pop & fade, chunkier face); the
// splash script toggles #spinner via hidden, an HTMLElement-only idiom, so the
// SMIL svg rides inside a div because the CSP (style-src 'self') forbids
// inline style elements/attributes.
writeFileSync(DESKTOP_OUT, `<div id="spinner" aria-hidden="true"><svg width="64" height="64" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
${innerTwinkleSmil(flat16, sched16, TW_INSET, 0.18)}
</svg></div>
`)

// startup.html ships the same splash svg inline; rewrite its spinner div so
// the hand-maintained copy can never drift from the generated one.
const STARTUP_OUT = `${ROOT}/apps/desktop/renderer/startup.html`
const startup = readFileSync(STARTUP_OUT, 'utf8')
writeFileSync(STARTUP_OUT, startup.replace(/<div id="spinner" aria-hidden="true">[\s\S]*?<\/svg><\/div>/, `<div id="spinner" aria-hidden="true"><svg width="64" height="64" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
${innerTwinkleSmil(flat16, sched16, TW_INSET, 0.18)}
</svg></div>`))

// The vscode twin's empty-editor letterpress is the derived 16-grid twinkle
// face (the chunkier grid the big sizes prefer), themed per variant. Source
// copies live in the fork; the staged dist carries the same bytes so a running
